S=Path(__file__).resolve().parents[1];cat=json.loads((S/'data/catalog.json').read_text(encoding='utf8'));out={}
n={'_初始金額萬':'初始帳戶金額，乘10000換實際現金；也是月重設的目標本金。非期貨保證金口數。','每月重設資金':'在策略實際呼叫的跨月節點，把交易帳戶淨值調回目標本金：有倉按比例調量後轉出獲利／補不足。影響後續下單量；報表仍重放買賣紀錄，不把轉出款當交易損失。','交易商品':'選實際交易資料；期貨本地日檔可含合約、開盤、日內進場及收盤欄位，指數用日OHLC模擬。未乘合約點值或換匯。','_交易成本比':'每次買入加收、賣出扣除此百分比×成交金額；下單量先乘(1−成本率)，估值也預扣平倉成本。不是固定每口費。','槓桿':'每次按可用Cash×此倍數計名目量，再除入場價並留成本；<=0不做該交易，未做期貨保證金驗證。','假日過濾':'使用時只允許下一筆資料日期恰等於當日+1日才收盤買入；以資料缺日推定，不另查國定假日表。','開低才空':'使用時比較基準當日open嚴格小於前一筆close才日內空；等於不空，不使用則略過此價格條件。','比較基準':'期貨可用標的指數或期貨自身判斷開低／均線；非期貨回到其自身日資料。改訊號資料，不改實際交易商品。','隔夜多槓桿':'當日收盤買、下一筆開盤賣的資金倍數，按該次帳戶現金計量。','日內空槓桿':'下一日trade_open放空到close回補的資金倍數，量以隔夜交易結束後現金計。','使用舊資料':'本版EnableLegacyDataDebug為false，即使設true也不啟用舊檔路徑；保留設定但無實際效用。','進出場時間':'只對TXF/KS200F/KQ150F選本地欄位：開盤08:45或09:00，日空進場晚1分鐘；台期收13:30/13:45，韓期15:30/15:45。其他商品不生效。','MA濾網天數':'比較基準的含當日收盤簡單平均筆數，最小視為1；不夠資料整組夜多及次日日空都跳過。','MA上_多槓桿':'前日比較基準close>=含當日均線，當晚隔夜多的現金倍數。','MA上_空槓桿':'同一個前日均線狀態下，次日日空的現金倍數；不是用當日尚未收盤價格判趨勢。','MA下_多槓桿':'前日比較基準close<均線時的隔夜多倍數。','MA下_空槓桿':'前日比較基準close<均線時次日日空倍數。','MA200下方買進倍數':'當日比較基準close<含當日MA200時，當晚隔夜多採此資金倍數；沒滿200筆不做夜多。','MA200MA20上方買進倍數':'close>=MA200且>=MA20時的隔夜多倍數；均線相等歸上方。','MA200上方MA20下方買進倍數':'close>=MA200但<MA20時的隔夜多倍數。','開盤低於前收放空倍數':'日內空的現金倍數；若關閉開低才空，即使未開低仍可用此量做空。'}
qty='共用帳戶用Cash×槓桿×(1−成本率)/入場價，向下截至6個有效數字；允許小數量，不檢查融券、保證金、借貸利息或真實整口規格。買入現金扣價金及成本，賣出增加扣成本後價金。'
report='一般單商品報表依各日交易紀錄重放現金與部位，再用該日open估殘倉並預扣成本，取樣每日最大回撤；交易次數是買賣紀錄筆數，不是完整來回數，也不是盤中最大回撤。'
data='資料先裁在本次起訖日期內才計指標，沒有另帶區間前的均線暖機資料。比較資料按同日精確查找，找不到不會借另一日代替。'
def add(name,summary,family,entry,exit,mechanics,caveats,notes={}):
 iid='SuperClaw/Stg'+name;nn=n|notes;out[iid]={'summary':summary,'family':family,'entry':entry,'exit':exit,'mechanics':mechanics,'caveats':caveats,'parameterNotes':{p['name']:nn[p['name']] for p in next(i for i in cat['items'] if i['id']==iid)['parameters']}}
add('BuyHold','第一次可執行報價以一倍資金買入持有，股票／指數末筆開盤平倉；期貨另以合約變動平舊開新。','持有',['資料至少兩筆才可能建倉；迴圈空手時以當日open及一倍現金換算買入。','持有中若期貨下一筆合約不同，按本日close平舊，下一日open重算一倍量買新。'],['最後一筆先平倉再終止：期貨用末筆close，非期貨用末筆open，沒有價差停損或停利。'],[qty,report,'跨月在非末筆迴圈先執行月重設，會按淨值比例調整倉量；若不開啟則現金與持倉自然累積。'],['首次進場後continue，該根不再檢查下一筆換月；若第一與第二筆就換合約，該次換月會被略過。','期貨與指數都採現金買賣模型及小數名目量，不是保證金／整口BuyHold。'])
add('隔夜做多','每個有效日收盤做多，下一筆資料開盤賣出，只持有收盤到隔日開盤的價差。','隔夜做多',['相鄰兩筆close、下一open為正，未被假日過濾且合約相同，按槓桿與當時現金於前日close買入。'],['下一筆資料open賣出全部現有部位；因逐對完整建倉平倉，末筆不另開隔夜倉。'],[qty,report,'跨月前後各可執行月重設；若月首仍持隔夜多，先按該open調量再賣，所以會有額外調量交易成本。'],['未開假日濾網時可跨多日空檔，仍視為一筆隔夜；合約不同一律不做該對，不自動換月延續。','沒有價格停損／停利，成本及跳空全部依資料開收價。'])
add('日內放空','依比較基準開低條件，在日內指定開盤價放空，當天收盤全部回補。','日內放空',['從第二筆資料起，前筆close、當日trade_open或open及close皆正；開低才空時需比較基準同日open<前收。','按Cash與槓桿換算量，在trade_open>0時用該欄，否則用open；期貨通常訊號開盤後一分鐘進場。'],['同日close用相同數量買回，不留隔夜；沒有盤中停損／停利。'],[qty,report,data],['開低訊號用比較資料open，實際放空可用trade_open，兩者不是同一價格。','每天只看開與收，回測不反映中途融券限制或維持保證金。'])
for name in ['夜多日空','夜多日空v3','多空三段']:
 ma=name=='夜多日空v3';three=name=='多空三段';time=name=='夜多日空'
 summary=('依MA200／MA20分三區調整夜多槓桿，另外配開低日空。' if three else '依比較基準均線上下切換夜多及日空槓桿。' if ma else '前日收盤做多到隔日開盤，再按開低條件放空到收盤；多空共用同一帳戶。')
 entry=['相鄰兩日資料有效時，若假日濾網允許且同合約，前日close按夜多倍數買，次日open退出；即使略過夜多，仍可獨立檢查當日日空。','隔夜交易後的現金決定日空量；開低才空開啟時需比較基準當日open<前收，實際在trade_open或open放空。']
 ex=['夜多在次日open賣全部現有量，日空同日close買回相同數量；資料末筆仍可完成前一夜及當日日空，但不再買下一夜。']
 mech=[qty,report,data];ca=['夜多與日空使用同一資金帳，先前損益改變後一段交易量；沒有盤中價格停損。','假日濾網與合約一致檢查只擋夜多，不擋日空。']
 if ma:
  entry.insert(0,'以夜多當日比較基準close與含該日收盤的MA比較：>=用MA上多／空倍數，<用MA下倍數；同一狀態同時決定當夜多及次日日空。')
  ca.append('均線不足時整個相鄰日對continue，連該次日空也不執行，與單純只停夜多不同。')
 elif three:
  entry.insert(0,'夜多當日比較基準close<MA200採第一倍數；否則>=MA20採第二倍數，剩下區域採第三倍數。日空用獨立固定放空倍數。')
  ca.append('比較資料不足200筆只令夜多槓桿為0，次日日空仍會檢查；不是整組策略等滿200筆才開始。')
 else:
  mech.append('僅TXF/KS200F/KQ150F能選實際資料開／日空／收盤欄位；韓期早盤0845/0846缺空值時改0900/0901並修紀錄時刻。其他商品沿其資料標準時刻。')
  ca.append('使用舊資料欄位被程式常數關閉，設true也不切舊檔。進出場時間對支援期貨會改讀價格欄位，並非只改交易紀錄標籤。')
 add(name,summary,'隔夜與日內組合',entry,ex,mech,ca)
notes={'交易商品':'商品1，可配置長期持有與MA篩選日空兩個子帳戶；初始比例為(1−交易商品2比)，不是固定日本市場限定。','交易商品2':'商品2，以獨立帳戶作夜多日空，不限制為韓國市場；仍依所選商品資料與時刻。','交易商品2比':'0到1的外層資金比，超界夾到端點；0不載商品2，1不載商品1。','每月內層平衡':'商品1新月首個有效日，把其空帳與持有帳淨值按空方策略比重新分配並調持有量；不移商品2比例。','每月外層平衡':'以商品1新月首個有效日啟動，將三帳總值按商品1／2比及空方策略比重新分配；用商品1前收估持有帳，再於當日open調量。','空方策略比':'商品1資金裡的日空帳戶比例，夾0到1；剩餘為持有帳。限制配置，不是實際持倉多空淨額。','MA空濾網天數':'商品1前日比較基準收盤的簡單均線筆數，至少視為1；不足不做該日商品1空單。','MA上空槓桿':'商品1前日比較基準close>=其MA時，商品1日空帳的名目倍數。','MA下空槓桿':'商品1前日比較基準close<其MA時的日空名目倍數。','開低才空1':'商品1比較基準當日open<前筆close才做商品1日空；不影響商品1持有帳。','比較基準1':'商品1日空判開低及前日均線可用其指數／期貨比較資料；實際交易仍商品1。','夜多槓桿':'商品2帳戶前日close買到當日open的倍數，受假日濾網及合約一致檢查。','日空槓桿':'商品2帳戶日內trade_open或open空到close的倍數，不受夜多假日濾網。','開低才空2':'商品2比較基準當日open<前筆close才日空；不擋其隔夜多。','比較基準2':'商品2判開低的指數／期貨比較來源，不改實際商品2交易。','假日過濾':'只擋商品2下一筆日期不是當日+1日的夜多；不影響日空或商品1持有。'}
add('東北亞一號','把資金分成商品1持有、商品1均線日空、商品2夜多日空三帳，按月調配與各自槓桿交易，形成多商品組合。','多商品配置',['商品1內部分長持與日空資金；長持帳以open建倉，日空帳以前日比較收盤對MA選倍數，按當日開低條件放空至收盤。','商品2獨立現金帳於前日close夜多到當日open，再依自己比較基準開低條件日空到close；假日或跨合約只略過夜多。','商品2比=0且空方策略比=0時走簡化純商品1持有分支，以首有效open建倉。'],['商品1持有帳用其最後有效open平倉，純持有特例也用最後open；日空當日close回補，夜多下一日open平掉。','無整體價格停損或跨商品價差收斂退出；它是多個資金帳的配置組合。'],[qty,'合併兩商品日期聯集，日期相同交易放到同一ledger並按交易時刻排序；組合報表各商品用當日close估值，休市日沿上一可用close，與一般單商品open估值不同。','商品1新月先外層、再內層平衡、最後可執行每月重設；先以前收估長持帳再於open調量。外層只是搬帳戶資金，持有調量才產生B/S紀錄；非B/S的帳戶淨值記錄不計交易損益。','外層／內層平衡與固定本金月重設不同：前者分配已有總值，後者把子帳回到初始配置本金。純商品2情況由商品2月份觸發重設。'],['所有名目價格共用同一數值資金單位，未做匯率換算或期貨保證金／點值乘數；跨市場時不能把配置當成實際可執行資金配置。','商品1持有分支沒有期貨換約平舊開新的步驟；商品2夜多才擋不同合約，選期貨時須注意持有帳交易代碼跨約帳差。','月首先在商品1分支重分配商品2現金，才處理商品2隔夜對：買單時間回填昨收，數量卻以已重分配的現金計。最終排序不重算下單量，不能當成完全按成交時刻逐筆決定資金。','商品1持有與日空可同時存在，但沒有兩腿價差訊號、避險比或均值回歸條件；不能依多商品名稱當成價差套利。'],notes)
