p=S/'programs.json';v=json.loads(p.read_text(encoding='utf8'));v['SuperClaw']='以指數或期貨日資料模擬持有、隔夜多、開低日空，以及均線調槓桿的夜多日空；東北亞一號擴為三帳、多商品配置與月平衡。交易量依現金與百分比成本換算小數名目單位，來源可為外部日資料或本地指定時刻價格表。';p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote 7 SuperClaw explanations')
